import java.util.*;class RiverSplitEligibilityTest{public static void main(String[]a){var seaA=new RiverRibbon.Point(700,700,8,62,100000);var seaB=new RiverRibbon.Point(702,700,8,62,100000);var mouth=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(seaA,seaB,4,.9,0)));if(!mouth.islands.isEmpty())throw new AssertionError("Sea-level mouth selected as inland split");var inland=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(new RiverRibbon.Point(700,700,8,90,100000),new RiverRibbon.Point(702,700,8,90,100000),4,.8,0)));if(inland.islands.size()!=1)throw new AssertionError("Valid inland reach skipped");var global=new EnvironmentMap(EnvironmentMap.filled(2048*2048,87));global.water=EnvironmentMap.filled(2048*2048,90);global.river=EnvironmentMap.filled(2048*2048,1);if(inland.branchPlan(global,inland.islands.get(0),62)!=null)throw new AssertionError("Short reach cannot contain a dry bar safely");inland=new RiverRibbon.Network(List.of(new RiverRibbon.Segment(new RiverRibbon.Point(660,700,8,90,100000),new RiverRibbon.Point(740,700,8,90,100000),4,.8,0)));var bar=new RiverRibbon.SedimentIsland(700,700,24,2,0);var plan=inland.branchPlan(global,bar,62);if(plan==null||plan.water()!=90)throw new AssertionError("Valid split missing wet parent level");Arrays.fill(global.water,62);Arrays.fill(global.height,60);var ocean=new RiverRibbon.Network(inland.segments);if(ocean.branchPlan(global,bar,62)!=null)throw new AssertionError("Dry/ocean parent accepted as wet inland split");System.out.println("PASS: sea-level mouths are excluded; branch plans require an actual inland water surface");}}
